import sys

def sign(n):
    return (n > 0) - (n < 0)

def attacks(attacker, target, blockers):
    ar, ac = attacker
    tr, tc = target
    dr, dc = tr - ar, tc - ac
    if dr == 0 and dc == 0:
        return False
    if not (dr == 0 or dc == 0 or abs(dr) == abs(dc)):
        return False
    sr, sc = sign(dr), sign(dc)
    r, c = ar + sr, ac + sc
    while (r, c) != (tr, tc):
        if (r, c) in blockers:
            return False
        r += sr
        c += sc
    return True

def in_check(square, queens):
    qs = set(queens)
    return any(attacks(q, square, qs - {q}) for q in queens)

rows = []
for i in range(4):
    row = input()
    rows.append(row)

king = None
queens = []
for r in range(4):
    for c in range(4):
        ch = rows[r][c]
        if ch == 'k':
            king = (r, c)
        elif ch == 'Q':
            queens.append((r, c))

if not in_check(king, queens):
    print("NOT CHECKMATE")
else:
    kr, kc = king
    can_escape = False
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            nr, nc = kr + dr, kc + dc
            if 0 <= nr < 4 and 0 <= nc < 4:
                remaining = [q for q in queens if q != (nr, nc)]
                if not in_check((nr, nc), remaining):
                    can_escape = True
    print("CHECKMATE" if not can_escape else "NOT CHECKMATE")
